    function render() {
        renderControls();
        renderCards();
        renderOffers();
        renderStatus();
    }

    let previousCooldownActive = false;
    function refreshTimers() {
        renderControls();
        const cooldownActive = Date.now() < state.cooldownUntil;
        if (previousCooldownActive !== cooldownActive) renderOffers();
        previousCooldownActive = cooldownActive;
    }

